import { App, PluginSettingTab, Setting, Notice } from "obsidian";
import GitSyncPlugin from "./main";
import { DEFAULT_SETTINGS, SyncStrategy } from "./types";

export class GitSyncSettingTab extends PluginSettingTab {
  plugin: GitSyncPlugin;

  constructor(app: App, plugin: GitSyncPlugin) {
    super(app, plugin);
    this.plugin = plugin;
  }

  display(): void {
    const { containerEl } = this;
    containerEl.empty();

    containerEl.createEl("h2", { text: "Git 同步设置" });

    // --- Notes Repo Section ---
    containerEl.createEl("h3", { text: "笔记仓库" });

    new Setting(containerEl)
      .setName("远程地址")
      .setDesc("笔记的 Git 远程仓库地址（Gitee/GitHub HTTPS）")
      .addText((text) =>
        text
          .setPlaceholder("https://gitee.com/用户名/笔记.git")
          .setValue(this.plugin.settings.notesRepo.remoteUrl)
          .onChange(async (value) => {
            this.plugin.settings.notesRepo.remoteUrl = value;
            await this.plugin.saveSettings();
          })
      );

    new Setting(containerEl)
      .setName("访问令牌")
      .setDesc("笔记仓库的个人访问令牌（Token）")
      .addText((text) =>
        text
          .setPlaceholder("ghp_xxx 或 Gitee 令牌")
          .setValue(this.plugin.settings.notesRepo.token)
          .onChange(async (value) => {
            this.plugin.settings.notesRepo.token = value;
            await this.plugin.saveSettings();
          })
      )
      .addButton((btn) =>
        btn.setButtonText("测试令牌").onClick(async () => {
          const url = this.plugin.settings.notesRepo.remoteUrl;
          const token = this.plugin.settings.notesRepo.token;
          if (!url || !token) {
            new Notice("请先填写远程地址和令牌");
            return;
          }
          btn.setButtonText("测试中...");
          btn.setDisabled(true);
          try {
            const result = await this.plugin.testGitAuth(url, token);
            new Notice(result.ok ? `✓ 令牌有效：${result.message}` : `✗ 令牌无效：${result.message}`);
          } catch (e: any) {
            new Notice(`✗ 测试失败：${e.message || e}`);
          }
          btn.setButtonText("测试令牌");
          btn.setDisabled(false);
        })
      );

    // --- Config Repo Section ---
    containerEl.createEl("h3", { text: "配置仓库（.obsidian/）" });

    new Setting(containerEl)
      .setName("启用配置仓库")
      .setDesc("将 .obsidian/ 目录（插件、主题、设置）单独同步到另一个仓库")
      .addToggle((toggle) =>
        toggle
          .setValue(this.plugin.settings.configRepo.enabled)
          .onChange(async (value) => {
            this.plugin.settings.configRepo.enabled = value;
            await this.plugin.saveSettings();
            this.display();
          })
      );

    if (this.plugin.settings.configRepo.enabled) {
      new Setting(containerEl)
        .setName("配置仓库远程地址")
        .setDesc("配置仓库的 Git 远程地址")
        .addText((text) =>
          text
            .setPlaceholder("https://gitee.com/用户名/obsidian-config.git")
            .setValue(this.plugin.settings.configRepo.remoteUrl)
            .onChange(async (value) => {
              this.plugin.settings.configRepo.remoteUrl = value;
              await this.plugin.saveSettings();
            })
        );

      new Setting(containerEl)
        .setName("配置仓库访问令牌")
        .setDesc("配置仓库的个人访问令牌")
        .addText((text) =>
          text
            .setPlaceholder("ghp_xxx 或 Gitee 令牌")
            .setValue(this.plugin.settings.configRepo.token)
            .onChange(async (value) => {
              this.plugin.settings.configRepo.token = value;
              await this.plugin.saveSettings();
            })
        )
        .addButton((btn) =>
          btn.setButtonText("测试令牌").onClick(async () => {
            const url = this.plugin.settings.configRepo.remoteUrl;
            const token = this.plugin.settings.configRepo.token;
            if (!url || !token) {
              new Notice("请先填写远程地址和令牌");
              return;
            }
            btn.setButtonText("测试中...");
            btn.setDisabled(true);
            try {
              const result = await this.plugin.testGitAuth(url, token);
              new Notice(result.ok ? `✓ 令牌有效：${result.message}` : `✗ 令牌无效：${result.message}`);
            } catch (e: any) {
              new Notice(`✗ 测试失败：${e.message || e}`);
            }
            btn.setButtonText("测试令牌");
            btn.setDisabled(false);
          })
        );
    }

    // --- Sync Strategy ---
    containerEl.createEl("h3", { text: "同步策略" });

    new Setting(containerEl)
      .setName("同步方式")
      .setDesc("选择触发同步的时机")
      .addDropdown((dropdown) =>
        dropdown
          .addOption("manual", "仅手动触发")
          .addOption("startup-shutdown", "打开/关闭仓库时")
          .addOption("timer", "定时同步")
          .addOption("all", "全部启用")
          .setValue(this.plugin.settings.syncStrategy)
          .onChange(async (value) => {
            this.plugin.settings.syncStrategy = value as SyncStrategy;
            await this.plugin.saveSettings();
            this.plugin.applySyncStrategy();
          })
      );

    new Setting(containerEl)
      .setName("定时间隔（分钟）")
      .setDesc("定时同步的间隔时间")
      .addSlider((slider) =>
        slider
          .setLimits(1, 120, 1)
          .setValue(this.plugin.settings.timerInterval)
          .setDynamicTooltip()
          .onChange(async (value) => {
            this.plugin.settings.timerInterval = value;
            await this.plugin.saveSettings();
            this.plugin.applySyncStrategy();
          })
      );

    // --- LLM Settings ---
    containerEl.createEl("h3", { text: "DeepSeek 大模型" });

    new Setting(containerEl)
      .setName("API Key")
      .setDesc("DeepSeek API 密钥")
      .addText((text) =>
        text
          .setPlaceholder("sk-xxx")
          .setValue(this.plugin.settings.deepseekApiKey)
          .onChange(async (value) => {
            this.plugin.settings.deepseekApiKey = value;
            await this.plugin.saveSettings();
          })
      )
      .addButton((btn) =>
        btn.setButtonText("测试 API").onClick(async () => {
          const key = this.plugin.settings.deepseekApiKey;
          if (!key) {
            new Notice("请先填写 API Key");
            return;
          }
          btn.setButtonText("测试中...");
          btn.setDisabled(true);
          try {
            const result = await this.plugin.testDeepSeek();
            new Notice(result.ok ? `✓ API 正常：${result.message}` : `✗ API 异常：${result.message}`);
          } catch (e: any) {
            new Notice(`✗ 测试失败：${e.message || e}`);
          }
          btn.setButtonText("测试 API");
          btn.setDisabled(false);
        })
      );

    new Setting(containerEl)
      .setName("API 地址")
      .setDesc("DeepSeek API 端点地址")
      .addText((text) =>
        text
          .setPlaceholder("https://api.deepseek.com")
          .setValue(this.plugin.settings.deepseekUrl)
          .onChange(async (value) => {
            this.plugin.settings.deepseekUrl = value;
            await this.plugin.saveSettings();
          })
      );

    new Setting(containerEl)
      .setName("模型")
      .setDesc("DeepSeek 模型（deepseek-v4-flash 性价比最高，deepseek-v4-pro 质量更高）")
      .addDropdown((dropdown) =>
        dropdown
          .addOption("deepseek-v4-flash", "deepseek-v4-flash（推荐）")
          .addOption("deepseek-v4-pro", "deepseek-v4-pro（更高质量）")
          .setValue(this.plugin.settings.deepseekModel)
          .onChange(async (value) => {
            this.plugin.settings.deepseekModel = value;
            await this.plugin.saveSettings();
          })
      );

    new Setting(containerEl)
      .setName("LLM 提交间隔")
      .setDesc("1 = 每次提交都让 LLM 生成 commit 信息；N = 累积 N 次提交后总结一次")
      .addSlider((slider) =>
        slider
          .setLimits(1, 20, 1)
          .setValue(this.plugin.settings.llmCommitInterval)
          .setDynamicTooltip()
          .onChange(async (value) => {
            this.plugin.settings.llmCommitInterval = value;
            await this.plugin.saveSettings();
          })
      );

    // --- Debug ---
    containerEl.createEl("h3", { text: "调试" });

    new Setting(containerEl)
      .setName("调试模式")
      .setDesc("开启后同步过程会输出详细日志，通过命令面板「查看调试日志」查看")
      .addToggle((toggle) =>
        toggle
          .setValue(this.plugin.settings.debugMode)
          .onChange(async (value) => {
            this.plugin.settings.debugMode = value;
            await this.plugin.saveSettings();
          })
      );
  }
}
